package eval

func settlementsSuite() Suite {
	base := calendarAndWeatherSuite()
	return Suite{ID: "069-settlements", Name: "Campaign Play 069: Settlements", Tests: append(base.Tests,
		playTest("play-settlement-list-unauthenticated", "Settlement list requires authentication", "GET", "/v1/play/campaigns/play-1/settlements", nil, nil, 401, nil),
		playTest("play-settlement-player-create-forbidden", "Players cannot create settlements", "POST", "/v1/play/campaigns/play-1/settlements", map[string]any{"settlement_id": "settle-phandalin", "name": "Phandalin", "services": []any{"inn", "smithy"}, "availability": "open"}, map[string]string{"Authorization": playerAAuth}, 403, nil),
		playTest("play-settlement-invalid-id", "Settlement creation requires a nonempty ID", "POST", "/v1/play/campaigns/play-1/settlements", map[string]any{"settlement_id": "", "name": "Phandalin", "services": []any{"inn"}, "availability": "open"}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTest("play-settlement-invalid-name", "Settlement creation requires a nonempty name", "POST", "/v1/play/campaigns/play-1/settlements", map[string]any{"settlement_id": "settle-empty-name", "name": "", "services": []any{"inn"}, "availability": "open"}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTest("play-settlement-empty-services", "Settlement services must be nonempty", "POST", "/v1/play/campaigns/play-1/settlements", map[string]any{"settlement_id": "settle-empty-services", "name": "Empty Services", "services": []any{}, "availability": "open"}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTest("play-settlement-duplicate-services", "Settlement services must be unique after normalization", "POST", "/v1/play/campaigns/play-1/settlements", map[string]any{"settlement_id": "settle-dup-services", "name": "Duplicate Services", "services": []any{"inn", " inn "}, "availability": "open"}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTest("play-settlement-invalid-availability", "Settlement availability must be a known status", "POST", "/v1/play/campaigns/play-1/settlements", map[string]any{"settlement_id": "settle-bad-status", "name": "Bad Status", "services": []any{"inn"}, "availability": "burning"}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTestExactJSON("play-settlement-create-phandalin", "DM creates a settlement with deterministic fields", "POST", "/v1/play/campaigns/play-1/settlements", map[string]any{"settlement_id": "settle-phandalin", "name": "Phandalin", "services": []any{"inn", "smithy", "temple"}, "availability": "open"}, map[string]string{"Authorization": dmAuth}, 201, map[string]any{"settlement_id": "settle-phandalin", "name": "Phandalin", "services": []any{"inn", "smithy", "temple"}, "availability": "open", "discovered_by": []any{}}),
		playTest("play-settlement-duplicate-id", "Duplicate settlement IDs conflict", "POST", "/v1/play/campaigns/play-1/settlements", map[string]any{"settlement_id": "settle-phandalin", "name": "Other Phandalin", "services": []any{"inn"}, "availability": "open"}, map[string]string{"Authorization": dmAuth}, 409, nil),
		playTestExactJSON("play-settlement-create-conyberry", "DM creates an undiscovered settlement for player filtering", "POST", "/v1/play/campaigns/play-1/settlements", map[string]any{"settlement_id": "settle-conyberry", "name": "Conyberry", "services": []any{"market"}, "availability": "limited"}, map[string]string{"Authorization": dmAuth}, 201, map[string]any{"settlement_id": "settle-conyberry", "name": "Conyberry", "services": []any{"market"}, "availability": "limited", "discovered_by": []any{}}),
		playTestExactJSON("play-settlements-player-before-discovery", "Players see no undiscovered settlements", "GET", "/v1/play/campaigns/play-1/settlements", nil, map[string]string{"Authorization": playerAAuth}, 200, map[string]any{"settlements": []any{}}),
		playTest("play-settlement-discover-dm-forbidden", "DM cannot use the player discovery endpoint", "POST", "/v1/play/campaigns/play-1/settlements/settle-phandalin/discover", nil, map[string]string{"Authorization": dmAuth}, 403, nil),
		playTest("play-settlement-discover-unknown", "Unknown settlement discovery returns 404", "POST", "/v1/play/campaigns/play-1/settlements/settle-missing/discover", nil, map[string]string{"Authorization": playerAAuth}, 404, nil),
		playTestExactJSON("play-settlement-discover-player-a", "Player A discovers a settlement once", "POST", "/v1/play/campaigns/play-1/settlements/settle-phandalin/discover", nil, map[string]string{"Authorization": playerAAuth}, 201, map[string]any{"settlement_id": "settle-phandalin", "name": "Phandalin", "services": []any{"inn", "smithy", "temple"}, "availability": "open", "discovered_by": []any{"play-char-a"}}),
		playTestExactJSON("play-settlement-discover-player-a-repeat", "Repeated discovery by the same player is idempotent", "POST", "/v1/play/campaigns/play-1/settlements/settle-phandalin/discover", nil, map[string]string{"Authorization": playerAAuth}, 200, map[string]any{"settlement_id": "settle-phandalin", "name": "Phandalin", "services": []any{"inn", "smithy", "temple"}, "availability": "open", "discovered_by": []any{"play-char-a"}}),
		playTestExactJSON("play-settlement-discover-player-b", "Player B discovery records a second character once", "POST", "/v1/play/campaigns/play-1/settlements/settle-phandalin/discover", nil, map[string]string{"Authorization": playerBAuth}, 201, map[string]any{"settlement_id": "settle-phandalin", "name": "Phandalin", "services": []any{"inn", "smithy", "temple"}, "availability": "open", "discovered_by": []any{"play-char-b"}}),
		playTest("play-settlement-player-update-forbidden", "Players cannot update settlements", "PUT", "/v1/play/campaigns/play-1/settlements/settle-phandalin", map[string]any{"name": "Phandalin", "services": []any{"inn"}, "availability": "closed"}, map[string]string{"Authorization": playerAAuth}, 403, nil),
		playTest("play-settlement-update-invalid-availability", "Settlement availability updates are validated", "PUT", "/v1/play/campaigns/play-1/settlements/settle-phandalin", map[string]any{"name": "Phandalin", "services": []any{"inn", "smithy"}, "availability": "unknown"}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTestExactJSON("play-settlement-update-availability", "DM updates settlement services and availability", "PUT", "/v1/play/campaigns/play-1/settlements/settle-phandalin", map[string]any{"name": "Phandalin Rebuilt", "services": []any{"inn", "temple"}, "availability": "closed"}, map[string]string{"Authorization": dmAuth}, 200, map[string]any{"settlement_id": "settle-phandalin", "name": "Phandalin Rebuilt", "services": []any{"inn", "temple"}, "availability": "closed", "discovered_by": []any{"play-char-a", "play-char-b"}}),
		playTestExactJSON("play-settlements-read-dm", "DM sees all settlements and all discoverers in creation order", "GET", "/v1/play/campaigns/play-1/settlements", nil, map[string]string{"Authorization": dmAuth}, 200, map[string]any{"settlements": []any{
			map[string]any{"settlement_id": "settle-phandalin", "name": "Phandalin Rebuilt", "services": []any{"inn", "temple"}, "availability": "closed", "discovered_by": []any{"play-char-a", "play-char-b"}},
			map[string]any{"settlement_id": "settle-conyberry", "name": "Conyberry", "services": []any{"market"}, "availability": "limited", "discovered_by": []any{}},
		}}),
		playTestExactJSON("play-settlements-read-player-a", "Player A sees only discovered settlements and their own discovery identity", "GET", "/v1/play/campaigns/play-1/settlements", nil, map[string]string{"Authorization": playerAAuth}, 200, map[string]any{"settlements": []any{
			map[string]any{"settlement_id": "settle-phandalin", "name": "Phandalin Rebuilt", "services": []any{"inn", "temple"}, "availability": "closed", "discovered_by": []any{"play-char-a"}},
		}}),
		playTestExactJSON("play-settlements-read-player-b", "Player B sees only discovered settlements and their own discovery identity", "GET", "/v1/play/campaigns/play-1/settlements", nil, map[string]string{"Authorization": playerBAuth}, 200, map[string]any{"settlements": []any{
			map[string]any{"settlement_id": "settle-phandalin", "name": "Phandalin Rebuilt", "services": []any{"inn", "temple"}, "availability": "closed", "discovered_by": []any{"play-char-b"}},
		}}),
	)}
}
